mapper.insert:
INSERT INTO PAYMENT_HISTORY (
    PAYMENT_ID
  , USER_ID
  , SUBSCRIPTION_ID
  , PG_TRANSACTION_ID
  , PAYMENT_KEY
  , AMOUNT
  , STATUS
  , APPROVED_AT
  , RAW_RESPONSE
  , REG_ID
) VALUES (
    NEXTVAL('payment_history_seq')
  , #{userId}
  , #{subscriptionId, jdbcType=NUMERIC}
  , #{pgTransactionId}
  , #{paymentKey}
  , #{amount}
  , #{status}
  , #{approvedAt, jdbcType=TIMESTAMP}
  , #{rawResponse, jdbcType=OTHER}::jsonb
  , ''
)
